-- Catalog-only update; authored quest instances are preserved.
insert into public.catalog_entries (kind, external_id, name, description, status, image_path, metadata) select kind, external_id, name, description, status, image_path, metadata from jsonb_to_recordset($seed$[{"kind":"minigame","external_id":"letter_drawing","name":"Letter Drawing","description":"Trace a typed English word or selected letters in order along authored strokes and points. Letter case is preserved; Open World exercises do not require uppercase/lowercase pairs.","status":null,"image_path":"images/minigames/letter_drawing.png","metadata":{"image":"images/minigames/letter_drawing.png","name":"Letter Drawing","unity_config":"LetterTracingQuestConfigSO","unity_content":"TracingLessonSO","category":"motor_skills","description":"Trace a typed English word or selected letters in order along authored strokes and points. Letter case is preserved; Open World exercises do not require uppercase/lowercase pairs.","english_focus":"Letter formation, stroke order","difficulty_range":[1,4],"content_fields":["drawingInputMode","word","symbols"],"variants":["trace_guided"],"typical_stations":["shop","chest","cart"]}}]$seed$::jsonb) as entries(kind text, external_id text, name text, description text, status text, image_path text, metadata jsonb) on conflict (kind, external_id) do update set name = excluded.name, description = excluded.description, status = excluded.status, image_path = excluded.image_path, metadata = excluded.metadata, updated_at = now();
